(function(root){
'use strict';
const levels=[['debutant','Découverte','Comprendre les mots et les pourcentages. Aucun prérequis.'],['pratique','Pratique','Relier risque, position et coûts avec des calculs mentaux simples.'],['avance','Analyse','Interpréter une annonce, un graphique et un test historique.'],['expert','Recherche','Repérer les biais et mettre une méthode à l’épreuve.']];
const choice=(id,level,topic,q,a,ok,why,hint)=>({id,level,topic,q,a,ok,why,hint,type:'choice'});
const number=(id,level,topic,q,expected,unit,why,hint)=>({id,level,topic,q,expected,unit,why,hint,type:'number'});
const bank=[
choice('d1','debutant','Sens du trade','Vous achetez un actif sans levier. Son prix monte de 5 %. Avant frais, votre position…',['Gagne 5 %','Perd 5 %','Gagne forcément 5 % de tout votre compte'],0,'La position gagne 5 %. Pour connaître le résultat sur tout le compte, il faut aussi connaître la part du compte investie.','Le rendement de la position et celui du compte ont des bases différentes.'),
choice('d2','debutant','Long et short','Une position short cherche à profiter de quelle évolution du prix ?',['Une hausse','Une baisse','Aucun changement'],1,'Une position short bénéficie d’une baisse du prix, avant coûts. Si le prix monte, elle perd de la valeur.','Long : sens de la hausse. Short : sens opposé.'),
number('d3','debutant','Pourcentage du compte','Le compte vaut 1 000 €. Combien représente 1 % de ce compte ?',10,'€','1 % signifie un centième : 1 000 ÷ 100 = 10 €. C’est un exercice de conversion, pas un niveau de risque conseillé.','Pour obtenir 1 %, divisez par 100.'),
choice('d4','debutant','Stop et budget','« Stop à −2 % du prix d’entrée » signifie-t-il automatiquement « perte de 2 % du compte » ?',['Oui, toujours','Oui, même avec une petite position','Non, cela dépend de la taille de la position'],2,'Le −2 % concerne le prix de l’actif. L’effet sur le compte dépend de l’exposition : la quantité détenue et le prix d’entrée.','Demandez-vous : pourcentage de quoi ?'),
choice('d5','debutant','Unités de temps','Une bougie M1 regroupe les variations sur…',['Un mois','Une minute','Une semaine'],1,'M1 signifie une minute. Dans cet atlas, MN désigne le mensuel. Ce sont des durées de bougie, pas des durées de détention imposées.','Le mensuel est noté MN dans ce site.'),
choice('d6','debutant','Coûts','Une position gagne 2 % avant frais. Les coûts représentent 0,5 % du même montant de référence. Quel est le gain net ?',['2,5 %','1,5 %','0,5 %'],1,'2 % − 0,5 % = 1,5 %. On peut soustraire ici parce que les deux pourcentages portent sur la même base.','Les coûts réduisent le résultat.'),
choice('d7','debutant','Données','Un graphique utilise des prix fictifs générés par le site. Un bon résultat prouve-t-il que la méthode fonctionne sur Bitcoin ?',['Oui, si la courbe monte','Non, il faut des données pertinentes et une validation','Oui, si le test a beaucoup de trades'],1,'Une série fictive sert à comprendre le calcul. Elle ne constitue pas un historique Bitcoin et ne démontre pas une performance de marché.','La première question est : d’où viennent les données ?'),
choice('d8','debutant','Incertitude','Une analyse paraît convaincante. Quelle conclusion est justifiée ?',['La hausse est certaine','Le risque a disparu','C’est un scénario qui peut être invalidé'],2,'Une analyse propose un scénario. Il faut préciser ce qui le contredirait ; une belle explication ne garantit pas son issue.','Un scénario reste une hypothèse.'),
number('p1','pratique','Risque du compte','Vous investissez 50 % du compte dans une position longue sans levier. Elle baisse de 2 %. Hors frais, quelle perte cela représente-t-il en % du compte ? Saisissez une valeur positive.',1,'% du compte','La moitié du compte subit −2 % : 50 % × 2 % = 1 % du compte. Le reste est supposé rester en liquidités, sans variation.','La moitié de 2 %, c’est…'),
choice('p2','pratique','Dimensionnement','Budget de perte prévu : 1 % du compte. Stop à −2 % du prix d’entrée d’un achat. Quelle exposition théorique, hors frais et avec exécution exacte au stop ?',['25 % du compte','50 % du compte','100 % du compte'],1,'Exposition = risque du compte ÷ distance du stop : 1 % ÷ 2 % = 0,5, donc 50 % du compte. Il s’agit d’un modèle linéaire.','À pleine exposition, une baisse de 2 % ferait perdre 2 % du compte.'),
choice('p3','pratique','Ajuster la taille','Même budget de risque : la distance du stop passe de 2 % à 4 %. Hors frais, la taille de position doit…',['Doubler','Rester identique','Être divisée par deux'],2,'Une perte deux fois plus grande par unité impose deux fois moins d’unités pour garder la même perte totale prévue.','Distance × taille : le produit doit rester identique.'),
choice('p4','pratique','Exécution','Vous prévoyez un stop à −2 % du prix d’entrée. Le marché saute directement à −4 %. La perte est-elle forcément limitée à −2 % sur la position ?',['Oui, tout stop garantit le prix','Non, l’exécution peut être plus défavorable','Oui, si le budget de risque est faible'],1,'Un stop au marché ne garantit pas le prix d’exécution. Le budget de risque est une perte planifiée, pas une protection absolue contre un saut de prix.','Le déclenchement de l’ordre et son prix d’exécution sont distincts.'),
number('p5','pratique','Rapport gain / risque','Objectif à +6 % du prix d’entrée ; stop à −2 %. Hors frais, combien de fois le gain visé représente-t-il la perte prévue ?',3,'R','6 ÷ 2 = 3. Le rapport est 3R : le gain visé vaut trois fois la perte prévue. Cela ne donne pas la probabilité de réussite.','Combien de groupes de 2 dans 6 ?'),
choice('p6','pratique','Short','Vous vendez à découvert. Le prix de l’actif baisse de 5 %. Le gain brut représente…',['5 % du notionnel initial vendu','5 % du compte, quelle que soit la taille','Une perte de 5 % du notionnel initial'],0,'Quantité × baisse du prix = gain brut. Le pourcentage est ici rapporté à la valeur initiale vendue ; le rendement du compte dépend de l’exposition, des frais et de l’emprunt.','Un short profite d’une baisse ; vérifiez ensuite la base du pourcentage.'),
choice('p7','pratique','Discipline','Votre objectif est un mouvement de 1 %. Le spread et les frais estimés absorbent presque tout ce mouvement. Quelle réaction est la plus cohérente ?',['Augmenter la taille pour effacer les coûts','Retirer le stop','Réexaminer le trade et pouvoir s’abstenir'],2,'Augmenter la taille augmente aussi les coûts en montant et le risque. Une idée directionnelle peut rester peu exploitable après coûts.','Une opportunité doit rester cohérente après les coûts.'),
choice('p8','pratique','Variation du capital','Le compte perd 10 %, puis gagne 10 % sur son nouveau montant. Revient-il exactement au départ ?',['Oui','Non, il reste légèrement en dessous','Non, il est légèrement au-dessus'],1,'Sur une base de 100 : 100 → 90 → 99. Les deux pourcentages ne s’appliquent pas au même montant. Aucun calcul complexe n’est nécessaire.','Prenez mentalement un capital de départ de 100.'),
choice('a1','avance','Espérance','Une méthode gagne une fois sur deux. Chaque gain vaut +2R et chaque perte −1R. Avant frais, son résultat moyen théorique est…',['Positif','Nul','Négatif'],0,'Sur deux trades représentatifs : +2R −1R = +1R, soit +0,5R par trade. Cette espérance dépend des hypothèses ; deux trades réels ne sont pas obligés de suivre ce partage.','Comparez un gain et une perte, plutôt que de calculer des probabilités.'),
choice('a2','avance','Macro','L’inflation dépasse le consensus, mais les actions montent. Quelle lecture est la plus rigoureuse ?',['Le marché se trompe forcément','L’inflation fait toujours monter les actions','Examiner composantes, révisions et attentes de taux'],2,'Une publication comporte plusieurs informations. Sa réaction dépend des attentes antérieures et du contexte. Le seul signe de la surprise ne suffit pas à expliquer chaque marché.','Le chiffre global ne raconte pas toute l’annonce.'),
choice('a3','avance','Corrélation','Dollar et actions montent ensemble pendant un mois. Cela prouve-t-il que le dollar fait monter les actions ?',['Oui','Non, ils peuvent répondre à un facteur commun','Oui, si la corrélation est forte'],1,'Une association ne prouve pas la causalité. Les deux marchés peuvent répondre à la croissance attendue ou à un autre facteur, et la relation peut changer.','Être simultané n’est pas forcément être la cause.'),
choice('a4','avance','Données futures','Un signal utilise la clôture de ce soir. Le backtest achète ce matin grâce à ce signal. Le test contient…',['Une information qui n’était pas encore disponible','Seulement des frais trop faibles','Aucun biais si le signal est bon'],0,'La clôture de ce soir était inconnue ce matin. Le test utilise une information future : son résultat ne décrit pas une stratégie exécutable ainsi.','Replacez-vous à l’heure exacte de la décision.'),
choice('a5','avance','Multihorizon','À 10 h, pour compléter une analyse M1, peut-on utiliser la clôture définitive de la bougie journalière du même jour ?',['Oui, le journalier est plus fiable','Non, elle n’est pas encore connue','Oui, si les deux tendances concordent'],1,'À 10 h, la bougie journalière reste ouverte. Sa clôture définitive appartient au futur ; il faut utiliser les données disponibles à 10 h ou la dernière bougie clôturée.','Un horizon supérieur n’autorise pas l’utilisation du futur.'),
choice('a6','avance','Ordre des événements','Dans une bougie M1, le plus haut atteint la cible et le plus bas atteint le stop. Les seuls prix ouverture/haut/bas/clôture disent-ils lequel arrive d’abord ?',['Oui, selon la couleur','Non, il manque l’ordre des variations','Oui, le stop arrive toujours avant'],1,'Ces quatre prix ne donnent pas la trajectoire intrabougie. Il faut des données plus fines ou une règle explicite pour traiter l’ambiguïté du test.','Deux trajectoires différentes peuvent produire la même bougie.'),
choice('a7','avance','Robustesse des coûts','Un backtest gagne légèrement avec des frais très faibles. Un glissement un peu plus élevé le rend perdant. Que cela révèle-t-il ?',['Une méthode sensible aux coûts, à examiner','Une preuve que le courtier triche','Il suffit de doubler le levier'],0,'Le résultat dépend fortement des hypothèses d’exécution. Il faut vérifier des coûts plausibles et la marge de sécurité ; le levier ne supprime pas cette fragilité.','Comparez l’avantage estimé à l’incertitude sur les coûts.'),
choice('a8','avance','Fréquence de réussite','Une méthode gagne 80 % du temps. Cette seule information suffit-elle à conclure qu’elle est rentable ?',['Oui, elle gagne plus souvent','Oui, si le marché est liquide','Non, il manque les montants gagnés, perdus et les coûts'],2,'Des pertes rares mais importantes peuvent dépasser de nombreux petits gains. Le taux de réussite seul ne détermine pas le résultat net.','Comptez la taille des gains et des pertes, pas seulement leur nombre.'),
choice('e1','expert','Surapprentissage','Sur 1 000 réglages, un seul est excellent ; ses voisins échouent. Quelle suite est la plus rigoureuse ?',['Retenir ce maximum et augmenter la taille','Examiner stabilité et données réellement inédites','Masquer les autres essais'],1,'Parmi beaucoup d’essais, un résultat chanceux peut ressortir. Un pic isolé invite à vérifier la robustesse et une validation indépendante, sans réutiliser celle-ci pour choisir le réglage.','Plus on essaie de réglages, plus on risque de sélectionner du hasard.'),
choice('e2','expert','Couverture','Vous avez deux expositions de même valeur, l’une longue, l’autre courte sur deux actifs. Le risque est-il nécessairement nul ?',['Oui, les montants s’annulent','Oui, si les actifs ont été corrélés','Non, ils peuvent diverger et avoir des coûts différents'],2,'Un montant net nul peut cacher deux grosses positions. La différence de comportement entre les actifs, le financement et l’exécution laissent des risques résiduels.','Net = différence des expositions ; brut = somme de leurs tailles.'),
choice('e3','expert','Biais de survivance','Vous testez depuis dix ans uniquement les actions qui appartiennent aujourd’hui à un indice. Quel problème peut apparaître ?',['Les anciennes entreprises sorties de l’indice sont ignorées','Le test comporte forcément trop de frais','Aucun, la liste actuelle est officielle'],0,'La composition actuelle omet certaines entreprises retirées ou disparues. Une simulation historique de cet univers doit tenir compte des constituants connus à chaque date.','La liste d’aujourd’hui était-elle connue dix ans plus tôt ?'),
choice('e4','expert','Révisions macro','Vous backtestez une réaction aux annonces de PIB avec les dernières valeurs révisées. Pourquoi est-ce problématique ?',['Le PIB ne peut jamais servir à une analyse','Les révisions sont toujours fausses','Ces valeurs pouvaient être inconnues à la date du signal'],2,'Il faut retrouver la version publiée à chaque date et son heure de disponibilité. Une série révisée après coup peut faire entrer de l’information future dans le test.','Distinguez date de la période mesurée et date de disponibilité de la valeur.'),
choice('e5','expert','Validation','Après chaque lecture de votre période de validation, vous changez les règles jusqu’à obtenir un bon résultat. Cette période est-elle encore indépendante ?',['Non, elle a participé au choix de la méthode','Oui, puisqu’elle porte le nom validation','Oui, si on a peu de paramètres'],0,'Les modifications ont exploité les résultats de cette période. Elle a donc servi à l’apprentissage ; il faut une nouvelle évaluation réellement séparée du choix des règles.','Une donnée influence la recherche dès qu’elle guide une modification.'),
choice('e6','expert','Dépendance','Cent alertes consécutives proviennent du même épisode de panique. Peut-on les traiter comme cent expériences indépendantes ?',['Oui, cent horodatages suffisent','Non, elles partagent un contexte et peuvent se recouvrir','Oui, si elles viennent de M1'],1,'Les observations proches peuvent être fortement dépendantes. Le nombre brut d’alertes peut surestimer la diversité de l’échantillon ; examiner événements, chevauchements et régimes.','Plusieurs photos du même événement ne sont pas plusieurs événements.'),
choice('e7','expert','Référence','Une stratégie gagne 10 % tandis que conserver l’actif gagne 20 %. Peut-on conclure avec ces deux chiffres seulement qu’elle est inutile ?',['Oui, moins de rendement suffit','Non, il faut aussi comparer risque, exposition, coûts et objectif','Non, toute stratégie positive est meilleure'],1,'Le rendement seul ne décrit ni le risque ni l’exposition. Une comparaison cohérente examine aussi les baisses, les périodes investies, les coûts et l’objectif de la stratégie.','Demandez ce qui a été risqué pour obtenir chaque résultat.'),
choice('e8','expert','Causalité et annonce','Un actif monte immédiatement après une annonce. Quelle preuve manque pour affirmer que cette annonce explique à elle seule toute la hausse ?',['Aucune, la proximité dans le temps suffit','Une bougie encore plus courte','Une analyse des autres informations et d’un scénario de comparaison crédible'],2,'La chronologie est une piste, pas une preuve causale suffisante. D’autres nouvelles, des positions préexistantes ou des flux peuvent intervenir simultanément.','Observer ce qui s’est passé ne révèle pas directement ce qui se serait passé sans l’annonce.')
];
function grade(q,input){if(q.type==='choice'){if(!Number.isInteger(input)||input<0||input>=q.a.length)return null;return input===q.ok}let raw=String(input??'').trim().replace(',','.');if(!/^[+-]?(\d+(\.\d*)?|\.\d+)$/.test(raw))return null;const value=Number(raw);if(!Number.isFinite(value))return null;return Math.abs(value-q.expected)<1e-8}
function session(items){return {items,index:0,answers:[],hint:false}}
function answer(s,input,skip=false){if(s.index>=s.items.length||s.answers.length>s.index)return null;const q=s.items[s.index],correct=skip?false:grade(q,input);if(correct===null)return null;const result={id:q.id,correct,skipped:skip,hint:s.hint};s.answers.push(result);return result}
function advance(s){if(s.answers.length!==s.index+1)return false;s.index++;s.hint=false;return true}
function stats(s){return {score:s.answers.filter(a=>a.correct).length,total:s.items.length,aided:s.answers.filter(a=>a.hint).length,missed:s.answers.filter(a=>!a.correct).map(a=>a.id)}}
function render(){
const key='ea-challenges-v1';let saved={};try{let obj=JSON.parse(localStorage.getItem(key)||'{}');if(obj&&typeof obj==='object'&&!Array.isArray(obj))saved=obj}catch{}let current=null,levelId=null,review=false,recorded=false;
$('#main').innerHTML=title('04 / À VOTRE RYTHME','Un pas, puis le suivant.','32 défis, quatre niveaux libres. Pourcentages clairement définis, calcul mental et raisonnement. Sans chronomètre. Les exemples sont fictifs ; le score mesure ces exercices.')+'<section class="section" style="padding-top:0"><div id="quizLevels"></div><div id="quiz" style="margin-top:28px"></div><p class="hint">Les résultats des séries terminées sont conservés dans ce navigateur. Une série en cours repart à zéro si vous quittez cette page. Les notes personnelles ci-dessous ne sont ni évaluées ni enregistrées.</p><p class="hint">Pour revoir les notions : <a class="text-link" href="#apprendre">bibliothèque pédagogique ↗</a> · <a class="text-link" href="https://www.investor.gov/introduction-investing/investing-basics/investment-products/stocks" target="_blank" rel="noopener noreferrer">Investor.gov : actions et frais ↗</a></p></section>';
function menu(){ $('#quizLevels').innerHTML='<div class="challenge-levels">'+levels.map(([id,name,desc],i)=>{let x=saved[id],valid=x&&Number.isInteger(x.score)&&x.score>=0&&x.score<=8;return '<article class="card"><span class="tag">NIVEAU '+(i+1)+' · 8 DÉFIS</span><h3>'+name+'</h3><p>'+desc+'</p><p class="hint">'+(valid?'Dernière série : '+x.score+'/8 · '+(Number.isInteger(x.aided)?x.aided:0)+' indice(s) utilisé(s).':'Pas encore de série terminée.')+'</p><button class="btn '+(levelId===id?'':'ghost')+'" data-level="'+id+'">'+(levelId===id?'Recommencer ce niveau':'Choisir ce niveau')+'</button></article>'}).join('')+'</div>';$$('[data-level]').forEach(b=>b.onclick=()=>start(b.dataset.level)) }
function start(id,items){levelId=id;review=!!items;recorded=false;current=session(items||bank.filter(q=>q.level===id));menu();show();$('#quiz').scrollIntoView({behavior:'smooth',block:'start'})}
function show(){let s=current;if(s.index>=s.items.length){const r=stats(s);if(!review&&!recorded){saved[levelId]={score:r.score,aided:r.aided,missed:r.missed};try{localStorage.setItem(key,JSON.stringify(saved))}catch{}recorded=true;menu()}const missed=s.items.filter(q=>r.missed.includes(q.id));$('#quiz').innerHTML='<div class="question"><span class="tag">'+(review?'RÉVISION':'SÉRIE TERMINÉE')+'</span><h2>'+r.score+' / '+r.total+'</h2><p>'+ (r.score===r.total?'Toutes les réponses de cette série sont correctes. Vous pouvez approfondir au niveau suivant ou refaire ces exercices.':'Les erreurs indiquent les notions à retravailler. Reprenez-les avec leur explication, sans limite de tentatives.')+'</p><p class="hint">'+r.aided+' question(s) avec indice. Résultat pédagogique, sans certification de compétence en trading.</p>'+(missed.length?'<h3>À revoir</h3><ul>'+missed.map(q=>'<li>'+esc(q.topic)+'</li>').join('')+'</ul><button class="btn" id="qReview">Revoir ces '+missed.length+' question(s)</button>':'')+'<div class="actions"><button class="btn ghost" id="qAgain">Refaire le niveau</button><a class="text-link" href="#apprendre">Revoir les notions ↗</a></div><p class="hint">Les révisions ne remplacent pas le résultat de la série complète.</p></div>';if(missed.length)$('#qReview').onclick=()=>start(levelId,missed);$('#qAgain').onclick=()=>start(levelId);return}
let q=s.items[s.index],selected=null;$('#quiz').innerHTML='<div class="question"><div class="eyebrow">'+esc(levels.find(l=>l[0]===levelId)[1])+' · '+(s.index+1)+' / '+s.items.length+' · '+esc(q.topic)+(review?' · RÉVISION':'')+'</div><progress value="'+s.index+'" max="'+s.items.length+'" aria-label="Questions terminées" style="width:100%;margin:16px 0"></progress><h3 id="qPrompt">'+esc(q.q)+'</h3><form id="qForm">'+(q.type==='choice'?'<div class="answers" role="group" aria-labelledby="qPrompt">'+q.a.map((a,i)=>'<button class="answer" type="button" aria-pressed="false" data-choice="'+i+'">'+String.fromCharCode(65+i)+' · '+esc(a)+'</button>').join('')+'</div>':'<label>Votre réponse ('+esc(q.unit)+')<input id="qNumber" type="text" inputmode="decimal" autocomplete="off" placeholder="Nombre uniquement, ex. 1 ou 0,5"></label>')+'<p id="qError" class="error" role="alert"></p><div class="actions"><button class="btn" type="submit" id="qValidate">Valider ma réponse</button><button class="btn ghost" type="button" id="qSkip">Je ne sais pas encore</button><button class="btn ghost" type="button" id="qHint">Un indice</button></div></form><p id="qHintText" class="notice" hidden></p><details><summary>Poser mon raisonnement (facultatif)</summary><label>Notes personnelles, sans correction automatique<textarea rows="3" maxlength="1500" placeholder="Le pourcentage porte sur… Mon raisonnement est…"></textarea></label></details><div id="feedback" aria-live="polite"></div><button class="btn" id="nextQ" hidden style="margin-top:20px">'+(s.index===s.items.length-1?'Voir le bilan':'Question suivante →')+'</button></div>';
$$('[data-choice]').forEach(b=>b.onclick=()=>{selected=+b.dataset.choice;$$('[data-choice]').forEach(x=>{let on=x===b;x.setAttribute('aria-pressed',String(on));x.classList.toggle('selected',on)})});$('#qHint').onclick=()=>{s.hint=true;$('#qHintText').hidden=false;$('#qHintText').textContent=q.hint};
function submit(skip){const value=q.type==='choice'?selected:$('#qNumber').value;const result=answer(s,value,skip);if(!result){$('#qError').textContent=q.type==='choice'?'Choisissez une réponse, puis validez.':'Saisissez un nombre sans unité ; virgule ou point acceptés.';return}$('#qError').textContent='';$$('#qForm button, #qForm input').forEach(b=>b.disabled=true);$$('[data-choice]').forEach(b=>{const i=+b.dataset.choice;if(i===q.ok)b.classList.add('correct');else if(i===selected)b.classList.add('wrong')});$('#feedback').innerHTML='<div class="notice"><b>'+(result.skipped?'Prenons le temps de comprendre.':result.correct?'Bonne réponse.':'Voici comment raisonner.')+'</b><p>Réponse attendue : <strong>'+esc(q.type==='choice'?q.a[q.ok]:String(q.expected)+' '+q.unit)+'</strong></p><p>'+esc(q.why)+'</p></div>';$('#nextQ').hidden=false}
$('#qForm').onsubmit=e=>{e.preventDefault();submit(false)};$('#qSkip').onclick=()=>submit(true);$('#nextQ').onclick=()=>{if(advance(s))show()}}
menu();$('#quiz').innerHTML='<div class="notice"><b>Commencez où vous êtes à l’aise.</b> Découverte est conseillé pour débuter. Aucun niveau n’est verrouillé. Vous pouvez changer votre choix avant de valider, demander un indice ou afficher la correction avec « Je ne sais pas encore ».</div>';
}
const api={bank,levels,grade,session,answer,advance,stats,render};if(typeof module==='object'&&module.exports)module.exports=api;else root.QuizLab=api;
})(typeof window!=='undefined'?window:globalThis);
